materials.vertexShader:
uniform float minX;
uniform float spanX;
varying float vAcross;
void main() {
  // The plate's own UVs run diagonally, so the lamp cells are taken from
  // geometry instead: where this vertex sits along the plate's width.
  vAcross = (position.x - minX) / spanX;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

materials.fragmentShader:
uniform float lit;
uniform float go;
varying float vAcross;
void main() {
  float cell = floor(clamp(vAcross, 0.0, 0.999) * 3.0);
  float on = go > 0.5 ? 1.0 : step(cell + 0.5, lit);
  vec3 bulb = go > 0.5 ? vec3(0.18, 0.95, 0.48) : vec3(1.0, 0.22, 0.16);
  // Unlit lamps stay dark rather than disappearing: a gantry with three
  // empty holes reads as broken, one with three dim lenses reads as waiting.
  gl_FragColor = vec4(mix(bulb * 0.09, bulb * 1.8, on), 1.0);
}

uniform float threshold;
uniform float lineThickness;
uniform float lineOffset;
uniform vec3 backColor;
uniform vec3 frontColor;
varying vec2 vUv;
void main() {
  float d = max(abs(vUv.x - 0.5), abs(vUv.y - 0.5)) * 2.0;
  if (d > threshold) discard;
  float band = abs(threshold - d - lineOffset);
  float line = step(band, lineThickness * 0.5);
  gl_FragColor = vec4(mix(backColor, frontColor, line), 1.0);
}

uniform sampler2D map;
uniform float labelOffset;
uniform vec3 backColor;
uniform vec3 frontColor;
varying vec2 vUv;
void main() {
  vec2 p = vec2(vUv.x - labelOffset, vUv.y);
  if (p.x > 1.0 || p.x < 0.0) discard;
  float text = texture2D(map, p).r;
  gl_FragColor = vec4(mix(backColor, frontColor, text), 1.0);
}

