materials.vertexShader:
attribute float size;
attribute float alpha;
varying float vAlpha;
void main() {
  vAlpha = alpha;
  vec4 view = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = size * (300.0 / -view.z);
  gl_Position = projectionMatrix * view;
}

materials.fragmentShader:
uniform vec3 color;
varying float vAlpha;
void main() {
  vec2 p = gl_PointCoord - 0.5;
  float d = dot(p, p);
  if (d > 0.25) discard;
  gl_FragColor = vec4(color, vAlpha * pow(1.0 - d * 4.0, 1.6) * 0.42);
}

uniform vec3 color;
uniform float time;
uniform float repeat;
varying vec2 vUv;
void main() {
  vec2 uv = vec2(vUv.x * repeat, vUv.y - time * 0.2) * 2.0;
  float stripes = fract(uv.x + uv.y);
  float band = step(0.5, stripes);
  float fade = 1.0 - abs(vUv.y - 0.5) * 1.2;
  gl_FragColor = vec4(color, (0.25 + band * 0.45) * fade);
}

